/**
 * 类型定义统一导出
 */
export * from './dingtalk';
/**
 * 通用响应接口
 */
export interface BaseResponse<T = any> {
    success: boolean;
    message?: string;
    /** 错误码（如钉钉 API 返回的 code） */
    code?: string;
    data?: T;
}
/**
 * 能力提供者基础接口
 */
export interface AbilityProvider {
    name: string;
    version: string;
    initialize?(config?: any): Promise<void> | void;
    destroy?(): Promise<void> | void;
}
